using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioBevelChainValidation {
 public static void Run(){try{Validate();UnityEditor.EditorApplication.Exit(0);}catch(Exception e){UnityEngine.Debug.LogException(e);UnityEditor.EditorApplication.Exit(1);}}

 static readonly BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static int cases,failures;static double smallest=1;static StringBuilder report=new StringBuilder();
 static string PathName=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-chain-result.txt"));
 static (int,int) Key(int a,int b)=>a<b?(a,b):(b,a);
 static List<(int a,int b)> Edges(StudioMeshCuts cuts){var seen=new HashSet<(Vector3,Vector3)>();var result=new List<(int,int)>();foreach(var face in cuts.Faces)for(int i=0;i<face.Vertices.Count;i++){int a=face.Vertices[i],b=face.Vertices[(i+1)%face.Vertices.Count];if(seen.Add(StudioMeshCuts.NormalEdgePositionKeyForBevel(cuts.Positions[a],cuts.Positions[b])))result.Add((a,b));}return result;}
 static List<int[]> Chains(StudioMeshCuts cuts,List<(int a,int b)> edges,int length){var positions=cuts.Positions;var ids=positions.Distinct().Select((p,i)=>(p,i)).ToDictionary(v=>v.p,v=>v.i);var ends=edges.Select(e=>(ids[positions[e.a]],ids[positions[e.b]])).ToArray();var result=new List<int[]>();var seen=new HashSet<string>();void Walk(int point,List<int> path,HashSet<int> vertices){if(path.Count==length){string sig=string.Join(",",path.OrderBy(i=>i));if(seen.Add(sig))result.Add(path.ToArray());return;}for(int e=0;e<ends.Length;e++){if(path.Contains(e))continue;int next=ends[e].Item1==point?ends[e].Item2:ends[e].Item2==point?ends[e].Item1:-1;if(next<0||vertices.Contains(next))continue;path.Add(e);vertices.Add(next);Walk(next,path,vertices);vertices.Remove(next);path.RemoveAt(path.Count-1);}}foreach(int point in ends.SelectMany(e=>new[]{e.Item1,e.Item2}).Distinct())Walk(point,new List<int>(),new HashSet<int>{point});return result;}
 static void Valid(StudioModelDocument.Node node){typeof(StudioBevelValidation).GetMethod("Valid",F).Invoke(null,new object[]{node,true});}
 static void Dump(StudioModelDocument.Node node,string name){var s=new StringBuilder();foreach(var p in node.mesh.vertices)s.AppendLine($"v {p.x:R} {p.y:R} {p.z:R}");foreach(var f in new StudioMeshCuts(node).Faces)s.AppendLine("f "+string.Join(" ",f.Vertices.Select(i=>(i+1).ToString())));File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+name+".obj")),s.ToString());}
 static void Probe(float initialWidth,Vector3 scale){var source=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);try{
 source.vertices=source.vertices.Select(p=>Vector3.Scale(p,scale)).ToArray();source.RecalculateBounds();var node=new StudioModelDocument.Node{mesh=source,cutPolygons=polygons,cutTriangles=source.triangles};var cuts=new StudioMeshCuts(node);var edge=Edges(cuts)[0];cuts.BevelEdges(node,new[]{edge},new StudioMeshCuts.BevelOptions{Width=initialWidth,Subdivisions=0,Tension=1,Junction=StudioMeshCuts.BevelJunction.Uniform});Valid(node);var after=new StudioMeshCuts(node);var edges=Edges(after);var chains=new[]{1,2,3}.SelectMany(length=>Chains(after,edges,length)).ToList();report.AppendLine("First width="+initialWidth+" scale="+scale+" source edges="+edges.Count+" chains="+chains.Count);
 foreach(var chain in chains){var mesh=Object.Instantiate(source);var next=new StudioModelDocument.Node{mesh=mesh,cutPolygons=node.cutPolygons,cutTriangles=node.cutTriangles,normalGroups=node.normalGroups};try{var selected=chain.Select(i=>edges[i]).ToArray();var topology=new StudioMeshCuts(next);foreach(float width in new[]{.001f,.01f,.05f,.15f,.449f,.85f,1f,.1f}){try{var result=topology.BevelEdges(next,selected,new StudioMeshCuts.BevelOptions{Width=width,Subdivisions=0,Tension=1,Junction=StudioMeshCuts.BevelJunction.Uniform});Valid(next);if(next.mesh.triangles.Distinct().Count()!=next.mesh.vertexCount)throw new Exception("Unreferenced vertices in result");var top=new StudioMeshCuts(next);foreach(var face in top.Faces){var a=top.Positions[face.Vertices[0]];double area=0,longest=0;for(int i=1;i+1<face.Vertices.Count;i++)area+=Vector3.Cross(top.Positions[face.Vertices[i]]-a,top.Positions[face.Vertices[i+1]]-a).magnitude*.5;foreach(int i in face.Vertices)longest=Math.Max(longest,(top.Positions[i]-a).sqrMagnitude);double ratio=area/Math.Max(longest,1e-30);if(ratio<smallest){smallest=ratio;if(ratio<1e-5){report.AppendLine("SLIVER first="+initialWidth+" chain="+string.Join(",",chain)+" requested="+width+" applied="+result.AppliedWidth+" ratio="+ratio);Dump(node,"bevel-sliver-source");Dump(next,"bevel-sliver-result");}}}cases++;}catch(Exception e){failures++;report.AppendLine("FAIL first="+initialWidth+" scale="+scale+" chain="+string.Join(",",chain)+" width="+width+" edges="+string.Join(";",chain.Select(i=>after.Positions[edges[i].a].ToString("R")+" -> "+after.Positions[edges[i].b].ToString("R")))+"\n"+(e.InnerException??e));if(failures==1){Dump(node,"bevel-chain-source");Dump(next,"bevel-chain-failure");}if(failures>=8)return;}}}finally{Object.DestroyImmediate(mesh);}}
 }finally{Object.DestroyImmediate(source);}}
 public static void Validate(){int exit=0;try{StudioIntegerScrubValidation.Validate();foreach(float width in new[]{.074f,.449f})foreach(var scale in new[]{Vector3.one,new Vector3(1,1.3f,2.1f)}){Probe(width,scale);if(failures>=8)goto Done;}Done:report.AppendLine("cases="+cases+" failures="+failures);if(failures>0)exit=1;}catch(Exception e){exit=1;report.AppendLine(e.ToString());}finally{File.WriteAllText(PathName,report.ToString());if(exit!=0)throw new Exception("Sequential bevel chain validation failed");}}
}
